"use client"; import {useEffect,useState} from "react"; import {clampPollInterval} from "@powerchain/realtime"; import {apiUrl} from "./api-base"; export function useLeaderboard(campaignId:string,pollMs=10_000){const [data,setData]=useState<unknown>(null);const [error,setError]=useState<string|null>(null);useEffect(()=>{let active=true;const load=async()=>{try{const r=await fetch(apiUrl(`/api/v1/leaderboard/${encodeURIComponent(campaignId)}`),{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const body=await r.json();if(active){setData(body.data);setError(null)}}catch(e){if(active)setError(e instanceof Error?e.message:"Leaderboard unavailable")}};void load();const id=setInterval(()=>void load(),clampPollInterval(pollMs));return()=>{active=false;clearInterval(id)}},[campaignId,pollMs]);return{data,error}}
